const assets = {"/":{"contentType":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>Signal Desk</title>\n    <link rel=\"stylesheet\" href=\"./styles.css\" />\n  </head>\n  <body>\n    <div class=\"app-shell\">\n      <header class=\"topbar\">\n        <div>\n          <p class=\"eyebrow\">WebMCP Challenge Concept</p>\n          <h1>Signal Desk</h1>\n          <p class=\"subtitle\">\n            A provenance-first intelligence workspace where agents can investigate, draft, and propose actions while humans keep review control.\n          </p>\n        </div>\n        <div class=\"topbar-actions\" aria-label=\"Demo controls\">\n          <div class=\"tool-status\" id=\"tool-status\" role=\"status\">\n            <span class=\"status-dot pending\" aria-hidden=\"true\"></span>\n            <span>Checking WebMCP</span>\n          </div>\n          <button class=\"button secondary\" id=\"select-critical\" type=\"button\">Focus Critical</button>\n          <button class=\"button\" id=\"reset-demo\" type=\"button\">Reset Demo</button>\n        </div>\n      </header>\n\n      <section class=\"scoreboard\" id=\"scoreboard\" aria-label=\"Workspace summary\"></section>\n\n      <main class=\"workspace\">\n        <section class=\"panel inbox-panel\" aria-labelledby=\"signals-heading\">\n          <div class=\"panel-header\">\n            <div>\n              <p class=\"eyebrow\">Inbox</p>\n              <h2 id=\"signals-heading\">Signals</h2>\n            </div>\n            <label class=\"search-box\">\n              <span>Search</span>\n              <input id=\"signal-search\" type=\"search\" placeholder=\"docs, admin, receipt\" />\n            </label>\n          </div>\n          <div class=\"filter-row\" id=\"signal-filters\" aria-label=\"Signal filters\"></div>\n          <div class=\"signal-list\" id=\"signal-list\"></div>\n        </section>\n\n        <section class=\"panel theme-panel\" aria-labelledby=\"themes-heading\">\n          <div class=\"panel-header\">\n            <div>\n              <p class=\"eyebrow\">Patterns</p>\n              <h2 id=\"themes-heading\">Themes</h2>\n            </div>\n            <span class=\"counter\" id=\"theme-count\"></span>\n          </div>\n          <div class=\"theme-list\" id=\"theme-list\"></div>\n        </section>\n\n        <section class=\"panel brief-panel\" aria-labelledby=\"brief-heading\">\n          <div class=\"panel-header\">\n            <div>\n              <p class=\"eyebrow\">Draft</p>\n              <h2 id=\"brief-heading\">Brief</h2>\n            </div>\n            <span class=\"status-pill\" id=\"brief-status\"></span>\n          </div>\n          <div id=\"brief-content\"></div>\n        </section>\n\n        <section class=\"panel actions-panel\" aria-labelledby=\"actions-heading\">\n          <div class=\"panel-header\">\n            <div>\n              <p class=\"eyebrow\">Review</p>\n              <h2 id=\"actions-heading\">Actions</h2>\n            </div>\n            <span class=\"counter\" id=\"action-count\"></span>\n          </div>\n          <div id=\"action-list\"></div>\n        </section>\n\n        <section class=\"panel detail-panel\" aria-labelledby=\"detail-heading\">\n          <div class=\"panel-header\">\n            <div>\n              <p class=\"eyebrow\">Evidence</p>\n              <h2 id=\"detail-heading\">Selected Signal</h2>\n            </div>\n          </div>\n          <div id=\"signal-detail\"></div>\n        </section>\n\n        <section class=\"panel audit-panel\" aria-labelledby=\"audit-heading\">\n          <div class=\"panel-header\">\n            <div>\n              <p class=\"eyebrow\">Provenance</p>\n              <h2 id=\"audit-heading\">Audit Trail</h2>\n            </div>\n          </div>\n          <ol class=\"audit-list\" id=\"audit-list\"></ol>\n        </section>\n      </main>\n    </div>\n    <script type=\"module\" src=\"./src/app.js\"></script>\n  </body>\n</html>\n"},"/index.html":{"contentType":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>Signal Desk</title>\n    <link rel=\"stylesheet\" href=\"./styles.css\" />\n  </head>\n  <body>\n    <div class=\"app-shell\">\n      <header class=\"topbar\">\n        <div>\n          <p class=\"eyebrow\">WebMCP Challenge Concept</p>\n          <h1>Signal Desk</h1>\n          <p class=\"subtitle\">\n            A provenance-first intelligence workspace where agents can investigate, draft, and propose actions while humans keep review control.\n          </p>\n        </div>\n        <div class=\"topbar-actions\" aria-label=\"Demo controls\">\n          <div class=\"tool-status\" id=\"tool-status\" role=\"status\">\n            <span class=\"status-dot pending\" aria-hidden=\"true\"></span>\n            <span>Checking WebMCP</span>\n          </div>\n          <button class=\"button secondary\" id=\"select-critical\" type=\"button\">Focus Critical</button>\n          <button class=\"button\" id=\"reset-demo\" type=\"button\">Reset Demo</button>\n        </div>\n      </header>\n\n      <section class=\"scoreboard\" id=\"scoreboard\" aria-label=\"Workspace summary\"></section>\n\n      <main class=\"workspace\">\n        <section class=\"panel inbox-panel\" aria-labelledby=\"signals-heading\">\n          <div class=\"panel-header\">\n            <div>\n              <p class=\"eyebrow\">Inbox</p>\n              <h2 id=\"signals-heading\">Signals</h2>\n            </div>\n            <label class=\"search-box\">\n              <span>Search</span>\n              <input id=\"signal-search\" type=\"search\" placeholder=\"docs, admin, receipt\" />\n            </label>\n          </div>\n          <div class=\"filter-row\" id=\"signal-filters\" aria-label=\"Signal filters\"></div>\n          <div class=\"signal-list\" id=\"signal-list\"></div>\n        </section>\n\n        <section class=\"panel theme-panel\" aria-labelledby=\"themes-heading\">\n          <div class=\"panel-header\">\n            <div>\n              <p class=\"eyebrow\">Patterns</p>\n              <h2 id=\"themes-heading\">Themes</h2>\n            </div>\n            <span class=\"counter\" id=\"theme-count\"></span>\n          </div>\n          <div class=\"theme-list\" id=\"theme-list\"></div>\n        </section>\n\n        <section class=\"panel brief-panel\" aria-labelledby=\"brief-heading\">\n          <div class=\"panel-header\">\n            <div>\n              <p class=\"eyebrow\">Draft</p>\n              <h2 id=\"brief-heading\">Brief</h2>\n            </div>\n            <span class=\"status-pill\" id=\"brief-status\"></span>\n          </div>\n          <div id=\"brief-content\"></div>\n        </section>\n\n        <section class=\"panel actions-panel\" aria-labelledby=\"actions-heading\">\n          <div class=\"panel-header\">\n            <div>\n              <p class=\"eyebrow\">Review</p>\n              <h2 id=\"actions-heading\">Actions</h2>\n            </div>\n            <span class=\"counter\" id=\"action-count\"></span>\n          </div>\n          <div id=\"action-list\"></div>\n        </section>\n\n        <section class=\"panel detail-panel\" aria-labelledby=\"detail-heading\">\n          <div class=\"panel-header\">\n            <div>\n              <p class=\"eyebrow\">Evidence</p>\n              <h2 id=\"detail-heading\">Selected Signal</h2>\n            </div>\n          </div>\n          <div id=\"signal-detail\"></div>\n        </section>\n\n        <section class=\"panel audit-panel\" aria-labelledby=\"audit-heading\">\n          <div class=\"panel-header\">\n            <div>\n              <p class=\"eyebrow\">Provenance</p>\n              <h2 id=\"audit-heading\">Audit Trail</h2>\n            </div>\n          </div>\n          <ol class=\"audit-list\" id=\"audit-list\"></ol>\n        </section>\n      </main>\n    </div>\n    <script type=\"module\" src=\"./src/app.js\"></script>\n  </body>\n</html>\n"},"/styles.css":{"contentType":"text/css; charset=utf-8","body":":root {\n  color-scheme: light;\n  --bg: #f4f5f1;\n  --panel: #ffffff;\n  --panel-soft: #f9faf6;\n  --text: #17201b;\n  --muted: #66736b;\n  --line: #dfe4dc;\n  --strong-line: #bfc9bf;\n  --green: #2e7a54;\n  --green-soft: #e4f2e8;\n  --amber: #9a641d;\n  --amber-soft: #f8edda;\n  --red: #a9443f;\n  --red-soft: #f7e4e2;\n  --blue: #2d5d89;\n  --blue-soft: #e3edf5;\n  --ink: #101613;\n  --shadow: 0 18px 40px rgba(23, 32, 27, 0.08);\n  font-family:\n    Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\",\n    sans-serif;\n}\n\n* {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  min-width: 320px;\n  background: var(--bg);\n  color: var(--text);\n}\n\nbutton,\ninput {\n  font: inherit;\n}\n\nbutton {\n  cursor: pointer;\n}\n\n.app-shell {\n  min-height: 100vh;\n  padding: 24px;\n}\n\n.topbar {\n  display: flex;\n  align-items: flex-end;\n  justify-content: space-between;\n  gap: 24px;\n  max-width: 1560px;\n  margin: 0 auto 18px;\n  padding: 20px 0 10px;\n}\n\n.eyebrow {\n  margin: 0 0 6px;\n  color: var(--green);\n  font-size: 0.72rem;\n  font-weight: 800;\n  letter-spacing: 0;\n  text-transform: uppercase;\n}\n\nh1,\nh2,\nh3,\nh4,\np {\n  margin-top: 0;\n}\n\nh1 {\n  margin-bottom: 8px;\n  color: var(--ink);\n  font-size: clamp(2.1rem, 4vw, 4rem);\n  line-height: 0.98;\n  letter-spacing: 0;\n}\n\nh2 {\n  margin-bottom: 0;\n  font-size: 1.1rem;\n  line-height: 1.1;\n  letter-spacing: 0;\n}\n\nh3 {\n  margin-bottom: 8px;\n  font-size: 0.98rem;\n  line-height: 1.25;\n  letter-spacing: 0;\n}\n\nh4 {\n  margin-bottom: 8px;\n  font-size: 0.82rem;\n  letter-spacing: 0;\n}\n\n.subtitle {\n  max-width: 760px;\n  margin-bottom: 0;\n  color: var(--muted);\n  font-size: 1rem;\n  line-height: 1.5;\n}\n\n.topbar-actions {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  justify-content: flex-end;\n  gap: 10px;\n}\n\n.tool-status {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  min-height: 38px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: var(--panel);\n  padding: 8px 10px;\n  color: var(--muted);\n  font-size: 0.78rem;\n  font-weight: 800;\n  white-space: nowrap;\n}\n\n.status-dot {\n  width: 9px;\n  height: 9px;\n  border-radius: 999px;\n  background: var(--amber);\n}\n\n.status-dot.available {\n  background: var(--green);\n}\n\n.status-dot.unavailable {\n  background: var(--red);\n}\n\n.button,\n.review-controls button,\n.evidence-links button,\n.chip {\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: var(--panel);\n  color: var(--text);\n  min-height: 38px;\n  padding: 9px 12px;\n  font-weight: 750;\n}\n\n.button {\n  border-color: var(--green);\n  background: var(--green);\n  color: #fff;\n}\n\n.button.secondary {\n  border-color: var(--strong-line);\n  background: var(--panel);\n  color: var(--text);\n}\n\n.scoreboard {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(120px, 1fr));\n  gap: 10px;\n  max-width: 1560px;\n  margin: 0 auto 16px;\n}\n\n.metric {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  min-height: 58px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: var(--panel);\n  padding: 12px 14px;\n  box-shadow: 0 10px 26px rgba(23, 32, 27, 0.05);\n}\n\n.metric span {\n  color: var(--muted);\n  font-size: 0.72rem;\n  font-weight: 850;\n  text-transform: uppercase;\n}\n\n.metric strong {\n  color: var(--ink);\n  font-size: 1.45rem;\n  line-height: 1;\n}\n\n.workspace {\n  display: grid;\n  grid-template-columns: minmax(280px, 1.15fr) minmax(260px, 0.9fr) minmax(320px, 1.25fr);\n  grid-template-areas:\n    \"inbox themes brief\"\n    \"inbox actions detail\"\n    \"audit audit detail\";\n  gap: 16px;\n  max-width: 1560px;\n  margin: 0 auto;\n  align-items: start;\n}\n\n.panel {\n  min-width: 0;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: var(--panel);\n  box-shadow: var(--shadow);\n}\n\n.inbox-panel {\n  grid-area: inbox;\n}\n\n.theme-panel {\n  grid-area: themes;\n}\n\n.brief-panel {\n  grid-area: brief;\n}\n\n.actions-panel {\n  grid-area: actions;\n}\n\n.detail-panel {\n  grid-area: detail;\n}\n\n.audit-panel {\n  grid-area: audit;\n}\n\n.panel-header {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 14px;\n  border-bottom: 1px solid var(--line);\n  padding: 16px;\n}\n\n.search-box {\n  display: grid;\n  gap: 5px;\n  min-width: 170px;\n  color: var(--muted);\n  font-size: 0.72rem;\n  font-weight: 800;\n  text-transform: uppercase;\n}\n\n.search-box input {\n  width: 100%;\n  min-height: 36px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  padding: 8px 10px;\n  color: var(--text);\n  text-transform: none;\n}\n\n.filter-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  border-bottom: 1px solid var(--line);\n  padding: 12px 16px;\n}\n\n.chip {\n  min-height: 32px;\n  padding: 6px 10px;\n  color: var(--muted);\n  text-transform: capitalize;\n}\n\n.chip.active {\n  border-color: var(--green);\n  background: var(--green-soft);\n  color: var(--green);\n}\n\n.signal-list,\n.theme-list,\n#brief-content,\n#action-list,\n#signal-detail,\n.audit-list {\n  padding: 14px;\n}\n\n.signal-list,\n.theme-list,\n.claim-list,\n#action-list,\n.audit-list {\n  display: grid;\n  gap: 10px;\n}\n\n.signal-card,\n.theme-card,\n.claim-card,\n.action-card,\n.detail-card {\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: var(--panel-soft);\n  padding: 13px;\n}\n\n.signal-card,\n.theme-card {\n  transition:\n    border-color 140ms ease,\n    background 140ms ease,\n    transform 140ms ease;\n}\n\n.signal-card:hover,\n.theme-card:hover {\n  border-color: var(--strong-line);\n  transform: translateY(-1px);\n}\n\n.signal-card.active,\n.theme-card.active {\n  border-color: var(--green);\n  background: #fbfefb;\n}\n\n.signal-card p,\n.theme-card p,\n.claim-card p,\n.action-card p,\n.detail-card p,\n.audit-list p,\n.brief-title p {\n  margin-bottom: 10px;\n  color: var(--muted);\n  font-size: 0.88rem;\n  line-height: 1.45;\n}\n\n.card-row,\n.meta-row,\n.audit-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n}\n\n.card-row {\n  margin-bottom: 9px;\n}\n\n.meta-row {\n  color: var(--muted);\n  font-size: 0.76rem;\n}\n\n.source,\n.owner,\n.claim-label,\n.confidence,\n.counter {\n  color: var(--muted);\n  font-size: 0.72rem;\n  font-weight: 850;\n  text-transform: uppercase;\n}\n\n.counter {\n  white-space: nowrap;\n}\n\n.priority,\n.state,\n.status-pill {\n  border-radius: 999px;\n  padding: 4px 8px;\n  font-size: 0.7rem;\n  font-weight: 850;\n  line-height: 1;\n  text-transform: uppercase;\n  white-space: nowrap;\n}\n\n.priority.critical,\n.state.rejected {\n  background: var(--red-soft);\n  color: var(--red);\n}\n\n.priority.high,\n.state.needs_edit {\n  background: var(--amber-soft);\n  color: var(--amber);\n}\n\n.priority.medium,\n.state.proposed,\n.status-pill.draft {\n  background: var(--blue-soft);\n  color: var(--blue);\n}\n\n.state.approved {\n  background: var(--green-soft);\n  color: var(--green);\n}\n\n.tag-row,\n.evidence-links,\n.linked-themes {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 7px;\n  margin-top: 10px;\n}\n\n.tag-row span,\n.linked-themes span {\n  border: 1px solid var(--line);\n  border-radius: 999px;\n  background: #fff;\n  padding: 4px 8px;\n  color: var(--muted);\n  font-size: 0.74rem;\n}\n\n.support-line {\n  color: var(--green);\n  font-size: 0.8rem;\n  font-weight: 800;\n}\n\n.brief-title {\n  border-bottom: 1px solid var(--line);\n  margin-bottom: 12px;\n  padding-bottom: 12px;\n}\n\n.evidence-links button {\n  min-height: 30px;\n  padding: 6px 9px;\n  background: #fff;\n  color: var(--blue);\n  font-size: 0.75rem;\n  text-align: left;\n}\n\n.review-controls {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 8px;\n  margin-top: 12px;\n}\n\n.review-controls button {\n  min-height: 34px;\n  padding: 7px 8px;\n  font-size: 0.75rem;\n}\n\n.review-controls.compact {\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  margin-top: 10px;\n}\n\n.review-controls.compact button {\n  min-height: 30px;\n  padding: 6px;\n  font-size: 0.68rem;\n}\n\ndl {\n  display: grid;\n  gap: 8px;\n  margin: 14px 0;\n}\n\ndl div {\n  display: grid;\n  grid-template-columns: 90px 1fr;\n  gap: 10px;\n  border-bottom: 1px solid var(--line);\n  padding-bottom: 8px;\n}\n\ndt {\n  color: var(--muted);\n  font-size: 0.74rem;\n  font-weight: 800;\n  text-transform: uppercase;\n}\n\ndd {\n  margin: 0;\n  color: var(--text);\n  font-size: 0.86rem;\n}\n\n.evidence-url {\n  display: inline-flex;\n  align-items: center;\n  min-height: 36px;\n  border: 1px solid var(--green);\n  border-radius: 8px;\n  padding: 8px 10px;\n  color: var(--green);\n  font-size: 0.84rem;\n  font-weight: 800;\n  text-decoration: none;\n}\n\n.linked-themes {\n  display: block;\n  margin-top: 16px;\n}\n\n.linked-themes span {\n  display: inline-flex;\n  margin: 0 6px 6px 0;\n}\n\n.audit-list {\n  list-style: none;\n  margin: 0;\n}\n\n.audit-list li {\n  border-left: 3px solid var(--green);\n  background: var(--panel-soft);\n  padding: 10px 12px;\n}\n\n.audit-head {\n  margin-bottom: 6px;\n  color: var(--muted);\n  font-size: 0.73rem;\n  font-weight: 800;\n  text-transform: uppercase;\n}\n\n.audit-list strong {\n  display: block;\n  margin-bottom: 5px;\n  font-size: 0.9rem;\n}\n\n.audit-list p {\n  margin-bottom: 0;\n}\n\n.empty-state {\n  border: 1px dashed var(--strong-line);\n  border-radius: 8px;\n  padding: 18px;\n  color: var(--muted);\n}\n\n@media (max-width: 1180px) {\n  .workspace {\n    grid-template-columns: 1fr 1fr;\n    grid-template-areas:\n      \"inbox brief\"\n      \"themes actions\"\n      \"detail detail\"\n      \"audit audit\";\n  }\n\n  .scoreboard {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n}\n\n@media (max-width: 760px) {\n  .app-shell {\n    padding: 14px;\n  }\n\n  .topbar {\n    align-items: stretch;\n    flex-direction: column;\n  }\n\n  .topbar-actions {\n    justify-content: stretch;\n  }\n\n  .button,\n  .tool-status {\n    flex: 1;\n  }\n\n  .workspace {\n    grid-template-columns: 1fr;\n    grid-template-areas:\n      \"inbox\"\n      \"themes\"\n      \"brief\"\n      \"actions\"\n      \"detail\"\n      \"audit\";\n  }\n\n  .panel-header {\n    flex-direction: column;\n  }\n\n  .search-box {\n    width: 100%;\n  }\n\n  .review-controls {\n    grid-template-columns: 1fr;\n  }\n\n  .scoreboard {\n    grid-template-columns: 1fr;\n  }\n}\n"},"/src/app.js":{"contentType":"text/javascript; charset=utf-8","body":"import { initialState } from \"./data.js\";\n\nconst stateKey = \"signal-desk-state-v1\";\nconst filters = [\"all\", \"critical\", \"high\", \"medium\", \"selected\"];\nlet activeFilter = \"all\";\nlet searchTerm = \"\";\nlet state = loadState();\n\nconst els = {\n  signalList: document.querySelector(\"#signal-list\"),\n  signalFilters: document.querySelector(\"#signal-filters\"),\n  signalSearch: document.querySelector(\"#signal-search\"),\n  themeList: document.querySelector(\"#theme-list\"),\n  themeCount: document.querySelector(\"#theme-count\"),\n  briefContent: document.querySelector(\"#brief-content\"),\n  briefStatus: document.querySelector(\"#brief-status\"),\n  actionList: document.querySelector(\"#action-list\"),\n  actionCount: document.querySelector(\"#action-count\"),\n  signalDetail: document.querySelector(\"#signal-detail\"),\n  auditList: document.querySelector(\"#audit-list\"),\n  resetDemo: document.querySelector(\"#reset-demo\"),\n  selectCritical: document.querySelector(\"#select-critical\"),\n  toolStatus: document.querySelector(\"#tool-status\"),\n  scoreboard: document.querySelector(\"#scoreboard\"),\n};\n\nconst reviewStates = [\"proposed\", \"approved\", \"rejected\", \"needs_edit\"];\nconst webMcpToolNames = [\n  \"search_signals\",\n  \"cluster_signals\",\n  \"draft_brief\",\n  \"explain_evidence\",\n  \"propose_actions\",\n  \"set_review_state\",\n  \"get_audit_trail\",\n  \"reset_demo\",\n];\n\nfunction clone(value) {\n  return JSON.parse(JSON.stringify(value));\n}\n\nfunction loadState() {\n  const saved = window.localStorage.getItem(stateKey);\n  if (!saved) return clone(initialState);\n\n  try {\n    return JSON.parse(saved);\n  } catch {\n    window.localStorage.removeItem(stateKey);\n    return clone(initialState);\n  }\n}\n\nfunction saveState() {\n  state.lastUpdated = new Date().toISOString();\n  window.localStorage.setItem(stateKey, JSON.stringify(state));\n}\n\nfunction resetDemo() {\n  state = clone(initialState);\n  activeFilter = \"all\";\n  searchTerm = \"\";\n  els.signalSearch.value = \"\";\n  saveState();\n  render();\n}\n\nfunction resetDemoWithAudit(actor = \"Human\") {\n  resetDemo();\n  addAudit(actor, \"Reset demo scenario\", \"Restored seeded signals, themes, brief, actions, and audit trail.\");\n  saveState();\n  render();\n}\n\nfunction addAudit(actor, action, detail) {\n  state.auditTrail.unshift({\n    id: `audit-${Date.now()}`,\n    actor,\n    action,\n    detail,\n    timestamp: new Date().toISOString(),\n  });\n}\n\nfunction getSignal(id) {\n  return state.signals.find((signal) => signal.id === id);\n}\n\nfunction getTheme(id) {\n  return state.themes.find((theme) => theme.id === id);\n}\n\nfunction getAction(id) {\n  return state.actions.find((action) => action.id === id);\n}\n\nfunction getActiveSignal() {\n  return getSignal(state.activeSignalId) || state.signals[0];\n}\n\nfunction formatDate(value) {\n  return new Intl.DateTimeFormat(\"en\", {\n    month: \"short\",\n    day: \"numeric\",\n    hour: \"2-digit\",\n    minute: \"2-digit\",\n  }).format(new Date(value));\n}\n\nfunction labelFor(value) {\n  return value.replace(\"_\", \" \");\n}\n\nfunction asToolResult(text, structuredContent = {}) {\n  return {\n    content: [{ type: \"text\", text }],\n    structuredContent,\n  };\n}\n\nfunction signalSummary(signal) {\n  return {\n    id: signal.id,\n    title: signal.title,\n    source: signal.source,\n    author: signal.author,\n    channel: signal.channel,\n    confidence: signal.confidence,\n    priority: signal.priority,\n    excerpt: signal.excerpt,\n    evidenceTags: signal.evidenceTags,\n    url: signal.url,\n  };\n}\n\nfunction themeSummary(theme) {\n  return {\n    id: theme.id,\n    name: theme.name,\n    summary: theme.summary,\n    confidence: theme.confidence,\n    reviewState: theme.reviewState,\n    signalIds: theme.signalIds,\n    evidence: theme.signalIds\n      .map((id) => getSignal(id))\n      .filter(Boolean)\n      .map((signal) => signalSummary(signal)),\n  };\n}\n\nfunction actionSummary(action) {\n  return {\n    id: action.id,\n    title: action.title,\n    owner: action.owner,\n    due: action.due,\n    state: action.state,\n    rationale: action.rationale,\n    evidenceSignalIds: action.evidenceSignalIds,\n  };\n}\n\nfunction allEvidenceIds() {\n  return new Set([\n    ...state.themes.flatMap((theme) => theme.signalIds),\n    ...state.brief.sections.flatMap((section) => section.evidenceSignalIds),\n    ...state.actions.flatMap((action) => action.evidenceSignalIds),\n  ]);\n}\n\nfunction reviewCounts() {\n  const reviewItems = [\n    ...state.themes.map((theme) => theme.reviewState),\n    ...state.brief.sections.map((section) => section.reviewState),\n    ...state.actions.map((action) => action.state),\n  ];\n\n  return reviewItems.reduce(\n    (counts, reviewState) => {\n      counts[reviewState] = (counts[reviewState] || 0) + 1;\n      return counts;\n    },\n    { proposed: 0, approved: 0, rejected: 0, needs_edit: 0 },\n  );\n}\n\nfunction updateToolStatus(status, label) {\n  const dotClass = status === \"available\" ? \"available\" : status === \"unavailable\" ? \"unavailable\" : \"pending\";\n  els.toolStatus.innerHTML = `\n    <span class=\"status-dot ${dotClass}\" aria-hidden=\"true\"></span>\n    <span>${label}</span>\n  `;\n}\n\nfunction renderScoreboard() {\n  const counts = reviewCounts();\n  els.scoreboard.innerHTML = `\n    <div class=\"metric\">\n      <span>Signals</span>\n      <strong>${state.signals.length}</strong>\n    </div>\n    <div class=\"metric\">\n      <span>Evidence Used</span>\n      <strong>${allEvidenceIds().size}</strong>\n    </div>\n    <div class=\"metric\">\n      <span>Approved</span>\n      <strong>${counts.approved}</strong>\n    </div>\n    <div class=\"metric\">\n      <span>Needs Review</span>\n      <strong>${counts.proposed + counts.needs_edit}</strong>\n    </div>\n  `;\n}\n\nfunction filteredSignals() {\n  return state.signals.filter((signal) => {\n    const matchesFilter =\n      activeFilter === \"all\" ||\n      signal.priority === activeFilter ||\n      signal.confidence === activeFilter ||\n      signal.status === activeFilter;\n    const haystack = [\n      signal.title,\n      signal.excerpt,\n      signal.source,\n      signal.author,\n      signal.channel,\n      ...signal.evidenceTags,\n    ]\n      .join(\" \")\n      .toLowerCase();\n    const matchesSearch = !searchTerm || haystack.includes(searchTerm);\n\n    return matchesFilter && matchesSearch;\n  });\n}\n\nfunction renderFilters() {\n  els.signalFilters.innerHTML = filters\n    .map(\n      (filter) => `\n        <button\n          class=\"chip ${activeFilter === filter ? \"active\" : \"\"}\"\n          type=\"button\"\n          data-filter=\"${filter}\"\n        >\n          ${labelFor(filter)}\n        </button>\n      `,\n    )\n    .join(\"\");\n}\n\nfunction renderSignals() {\n  const signals = filteredSignals();\n  els.signalList.innerHTML =\n    signals\n      .map(\n        (signal) => `\n          <article class=\"signal-card ${signal.id === state.activeSignalId ? \"active\" : \"\"}\" data-signal-id=\"${signal.id}\">\n            <div class=\"card-row\">\n              <span class=\"source\">${signal.source}</span>\n              <span class=\"priority ${signal.priority}\">${signal.priority}</span>\n            </div>\n            <h3>${signal.title}</h3>\n            <p>${signal.excerpt}</p>\n            <div class=\"meta-row\">\n              <span>${signal.author}</span>\n              <span>${formatDate(signal.timestamp)}</span>\n            </div>\n            <div class=\"tag-row\">\n              ${signal.evidenceTags.map((tag) => `<span>${tag}</span>`).join(\"\")}\n            </div>\n          </article>\n        `,\n      )\n      .join(\"\") || `<p class=\"empty-state\">No signals match this view.</p>`;\n}\n\nfunction renderThemes() {\n  els.themeCount.textContent = `${state.themes.length} themes`;\n  els.themeList.innerHTML = state.themes\n    .map((theme) => {\n      const supportCount = theme.signalIds.length;\n      return `\n        <article class=\"theme-card ${theme.id === state.activeThemeId ? \"active\" : \"\"}\" data-theme-id=\"${theme.id}\">\n          <div class=\"card-row\">\n            <span class=\"confidence\">${theme.confidence} confidence</span>\n            <span class=\"state ${theme.reviewState}\">${labelFor(theme.reviewState)}</span>\n          </div>\n          <h3>${theme.name}</h3>\n          <p>${theme.summary}</p>\n          <div class=\"support-line\">${supportCount} supporting signals</div>\n          <div class=\"review-controls compact\" data-review-theme-id=\"${theme.id}\">\n            <button type=\"button\" data-state=\"approved\">Approve</button>\n            <button type=\"button\" data-state=\"needs_edit\">Needs Edit</button>\n            <button type=\"button\" data-state=\"rejected\">Reject</button>\n          </div>\n        </article>\n      `;\n    })\n    .join(\"\");\n}\n\nfunction renderBrief() {\n  els.briefStatus.textContent = labelFor(state.brief.status);\n  els.briefStatus.className = `status-pill ${state.brief.status}`;\n  els.briefContent.innerHTML = `\n    <div class=\"brief-title\">\n      <h3>${state.brief.title}</h3>\n      <p>Updated by ${state.brief.updatedBy}</p>\n    </div>\n    <div class=\"claim-list\">\n      ${state.brief.sections\n        .map(\n          (section) => `\n            <article class=\"claim-card\">\n              <div class=\"card-row\">\n                <span class=\"claim-label\">${section.label}</span>\n                <span class=\"state ${section.reviewState}\">${labelFor(section.reviewState)}</span>\n              </div>\n              <p>${section.claim}</p>\n              <div class=\"evidence-links\">\n                ${section.evidenceSignalIds\n                  .map((id) => {\n                    const signal = getSignal(id);\n                    return `<button type=\"button\" data-signal-id=\"${id}\">${signal ? signal.title : id}</button>`;\n                  })\n                  .join(\"\")}\n              </div>\n              <div class=\"review-controls compact\" data-claim-id=\"${section.id}\">\n                <button type=\"button\" data-state=\"approved\">Approve</button>\n                <button type=\"button\" data-state=\"needs_edit\">Needs Edit</button>\n                <button type=\"button\" data-state=\"rejected\">Reject</button>\n              </div>\n            </article>\n          `,\n        )\n        .join(\"\")}\n    </div>\n  `;\n}\n\nfunction renderActions() {\n  els.actionCount.textContent = `${state.actions.length} actions`;\n  els.actionList.innerHTML = state.actions\n    .map(\n      (action) => `\n        <article class=\"action-card\">\n          <div class=\"card-row\">\n            <span class=\"owner\">${action.owner}</span>\n            <span class=\"state ${action.state}\">${labelFor(action.state)}</span>\n          </div>\n          <h3>${action.title}</h3>\n          <p>${action.rationale}</p>\n          <div class=\"meta-row\">\n            <span>Due ${action.due}</span>\n            <span>${action.evidenceSignalIds.length} evidence links</span>\n          </div>\n          <div class=\"evidence-links\">\n            ${action.evidenceSignalIds\n              .map((id) => {\n                const signal = getSignal(id);\n                return `<button type=\"button\" data-signal-id=\"${id}\">${signal ? signal.title : id}</button>`;\n              })\n              .join(\"\")}\n          </div>\n          <div class=\"review-controls\" data-action-id=\"${action.id}\">\n            <button type=\"button\" data-state=\"approved\">Approve</button>\n            <button type=\"button\" data-state=\"needs_edit\">Needs Edit</button>\n            <button type=\"button\" data-state=\"rejected\">Reject</button>\n          </div>\n        </article>\n      `,\n    )\n    .join(\"\");\n}\n\nfunction renderDetail() {\n  const signal = getActiveSignal();\n  if (!signal) {\n    els.signalDetail.innerHTML = `<p class=\"empty-state\">Select a signal to inspect evidence.</p>`;\n    return;\n  }\n\n  const linkedThemes = state.themes.filter((theme) => theme.signalIds.includes(signal.id));\n  const linkedClaims = state.brief.sections.filter((section) => section.evidenceSignalIds.includes(signal.id));\n  const linkedActions = state.actions.filter((action) => action.evidenceSignalIds.includes(signal.id));\n\n  els.signalDetail.innerHTML = `\n    <article class=\"detail-card\">\n      <div class=\"card-row\">\n        <span class=\"source\">${signal.source}</span>\n        <span class=\"confidence\">${signal.confidence} confidence</span>\n      </div>\n      <h3>${signal.title}</h3>\n      <p>${signal.excerpt}</p>\n      <dl>\n        <div><dt>Author</dt><dd>${signal.author}</dd></div>\n        <div><dt>Channel</dt><dd>${signal.channel}</dd></div>\n        <div><dt>Captured</dt><dd>${formatDate(signal.timestamp)}</dd></div>\n        <div><dt>Status</dt><dd>${labelFor(signal.status)}</dd></div>\n      </dl>\n      <a class=\"evidence-url\" href=\"${signal.url}\" target=\"_blank\" rel=\"noreferrer\">Open evidence source</a>\n      <div class=\"linked-themes\">\n        <h4>Linked themes</h4>\n        ${linkedThemes.map((theme) => `<span>${theme.name}</span>`).join(\"\") || \"<p>No linked themes.</p>\"}\n      </div>\n      <div class=\"linked-themes\">\n        <h4>Used in brief claims</h4>\n        ${linkedClaims.map((claim) => `<span>${claim.label}</span>`).join(\"\") || \"<p>No brief claims cite this signal.</p>\"}\n      </div>\n      <div class=\"linked-themes\">\n        <h4>Used in actions</h4>\n        ${linkedActions.map((action) => `<span>${action.title}</span>`).join(\"\") || \"<p>No actions cite this signal.</p>\"}\n      </div>\n    </article>\n  `;\n}\n\nfunction renderAudit() {\n  els.auditList.innerHTML = state.auditTrail\n    .slice(0, 8)\n    .map(\n      (entry) => `\n        <li>\n          <div class=\"audit-head\">\n            <span>${entry.actor}</span>\n            <time>${formatDate(entry.timestamp)}</time>\n          </div>\n          <strong>${entry.action}</strong>\n          <p>${entry.detail}</p>\n        </li>\n      `,\n    )\n    .join(\"\");\n}\n\nfunction render() {\n  renderScoreboard();\n  renderFilters();\n  renderSignals();\n  renderThemes();\n  renderBrief();\n  renderActions();\n  renderDetail();\n  renderAudit();\n}\n\nfunction selectSignal(signalId) {\n  const signal = getSignal(signalId);\n  if (!signal) return;\n\n  state.activeSignalId = signalId;\n  state.signals = state.signals.map((item) =>\n    item.id === signalId ? { ...item, status: \"selected\" } : item,\n  );\n  saveState();\n  render();\n}\n\nfunction setHumanReviewState(targetType, targetId, reviewState) {\n  if (!reviewStates.includes(reviewState)) return;\n\n  let target;\n  if (targetType === \"action\") {\n    target = getAction(targetId);\n    if (target && target.state !== reviewState) target.state = reviewState;\n  } else if (targetType === \"theme\") {\n    target = getTheme(targetId);\n    if (target && target.reviewState !== reviewState) target.reviewState = reviewState;\n  } else if (targetType === \"claim\") {\n    target = state.brief.sections.find((section) => section.id === targetId);\n    if (target && target.reviewState !== reviewState) target.reviewState = reviewState;\n  }\n\n  if (!target) return;\n  addAudit(\"Human\", `Marked ${targetType} ${labelFor(reviewState)}`, target.title || target.name || target.label);\n  saveState();\n  render();\n}\n\nfunction getModelContext() {\n  return document.modelContext || navigator.modelContext || null;\n}\n\nfunction searchSignalsTool({ query = \"\", priority = \"all\", confidence = \"all\", limit = 6 } = {}) {\n  const normalizedQuery = String(query).trim().toLowerCase();\n  const safeLimit = Math.max(1, Math.min(Number(limit) || 6, 20));\n  const matches = state.signals\n    .filter((signal) => {\n      const haystack = [\n        signal.title,\n        signal.excerpt,\n        signal.source,\n        signal.author,\n        signal.channel,\n        ...signal.evidenceTags,\n      ]\n        .join(\" \")\n        .toLowerCase();\n      const matchesQuery = !normalizedQuery || haystack.includes(normalizedQuery);\n      const matchesPriority = priority === \"all\" || signal.priority === priority;\n      const matchesConfidence = confidence === \"all\" || signal.confidence === confidence;\n\n      return matchesQuery && matchesPriority && matchesConfidence;\n    })\n    .slice(0, safeLimit)\n    .map((signal) => signalSummary(signal));\n\n  return asToolResult(`Found ${matches.length} matching signals.`, { signals: matches });\n}\n\nfunction clusterSignalsTool({ signalIds = [], minConfidence = \"medium\" } = {}) {\n  const selectedSignals = signalIds.length\n    ? signalIds.map((id) => getSignal(id)).filter(Boolean)\n    : state.signals.filter((signal) =>\n        minConfidence === \"high\"\n          ? signal.confidence === \"high\"\n          : [\"high\", \"medium\"].includes(signal.confidence),\n      );\n\n  if (!selectedSignals.length) {\n    return asToolResult(\"No matching signals were available to cluster.\", { themes: [] });\n  }\n\n  const signalIdSet = new Set(selectedSignals.map((signal) => signal.id));\n  state.themes = state.themes.map((theme) => ({\n    ...theme,\n    signalIds: theme.signalIds.filter((id) => signalIdSet.has(id) || !signalIds.length),\n    reviewState: theme.reviewState === \"approved\" ? \"approved\" : \"proposed\",\n  }));\n  state.activeThemeId = state.themes[0]?.id || state.activeThemeId;\n  addAudit(\n    \"Agent\",\n    `Clustered ${selectedSignals.length} signals`,\n    \"Refreshed theme support from the selected signal set while preserving evidence links.\",\n  );\n  saveState();\n  render();\n\n  return asToolResult(`Clustered ${selectedSignals.length} signals into ${state.themes.length} themes.`, {\n    themes: state.themes.map((theme) => themeSummary(theme)),\n  });\n}\n\nfunction draftBriefTool({ themeIds = [], title = \"\" } = {}) {\n  const selectedThemes = (themeIds.length ? themeIds : state.themes.map((theme) => theme.id))\n    .map((id) => getTheme(id))\n    .filter(Boolean);\n\n  if (!selectedThemes.length) {\n    return asToolResult(\"No themes were available for drafting.\", { brief: state.brief });\n  }\n\n  state.brief = {\n    title: title || \"Launch Intelligence Brief: Import Activation\",\n    status: \"draft\",\n    updatedBy: \"WebMCP agent\",\n    sections: selectedThemes.map((theme, index) => ({\n      id: `claim-agent-${index + 1}`,\n      label: index === 0 ? \"Primary risk\" : index === 1 ? \"Evidence pattern\" : \"Recommended move\",\n      claim:\n        index === 0\n          ? `${theme.name}: ${theme.summary}`\n          : `${theme.name} is supported by ${theme.signalIds.length} linked signals and should remain reviewable before action.`,\n      evidenceSignalIds: theme.signalIds.slice(0, 3),\n      reviewState: \"proposed\",\n    })),\n  };\n  addAudit(\n    \"Agent\",\n    `Drafted brief from ${selectedThemes.length} themes`,\n    \"Every generated claim carries linked supporting signals.\",\n  );\n  saveState();\n  render();\n\n  return asToolResult(`Drafted ${state.brief.sections.length} evidence-linked brief claims.`, {\n    brief: state.brief,\n  });\n}\n\nfunction explainEvidenceTool({ targetType = \"theme\", targetId = \"\" } = {}) {\n  if (targetType === \"claim\") {\n    const claim = state.brief.sections.find((section) => section.id === targetId);\n    if (!claim) return asToolResult(`Claim ${targetId} was not found.`, { evidence: [] });\n\n    const evidence = claim.evidenceSignalIds.map((id) => getSignal(id)).filter(Boolean).map(signalSummary);\n    return asToolResult(`Claim \"${claim.label}\" is supported by ${evidence.length} signals.`, {\n      target: claim,\n      evidence,\n    });\n  }\n\n  const theme = getTheme(targetId || state.activeThemeId);\n  if (!theme) return asToolResult(`Theme ${targetId} was not found.`, { evidence: [] });\n\n  return asToolResult(`Theme \"${theme.name}\" is supported by ${theme.signalIds.length} signals.`, {\n    theme: themeSummary(theme),\n  });\n}\n\nfunction proposeActionsTool({ themeIds = [], owner = \"Product\" } = {}) {\n  const selectedThemes = (themeIds.length ? themeIds : [state.activeThemeId])\n    .map((id) => getTheme(id))\n    .filter(Boolean);\n\n  if (!selectedThemes.length) {\n    return asToolResult(\"No themes were available for action proposals.\", { actions: [] });\n  }\n\n  const newActions = selectedThemes.map((theme, index) => ({\n    id: `act-agent-${Date.now()}-${index}`,\n    title: `Review response for ${theme.name.toLowerCase()}`,\n    owner,\n    due: \"2026-09-01\",\n    rationale: `Proposed from ${theme.signalIds.length} linked evidence signals. Human approval is required before execution.`,\n    evidenceSignalIds: theme.signalIds.slice(0, 3),\n    state: \"proposed\",\n  }));\n\n  state.actions = [...newActions, ...state.actions];\n  addAudit(\n    \"Agent\",\n    `Proposed ${newActions.length} actions`,\n    \"Actions were added as proposed items and require human review before execution.\",\n  );\n  saveState();\n  render();\n\n  return asToolResult(`Proposed ${newActions.length} approval-gated actions.`, {\n    actions: newActions.map((action) => actionSummary(action)),\n  });\n}\n\nfunction setReviewStateTool({ targetType = \"action\", targetId = \"\", reviewState = \"needs_edit\" } = {}) {\n  if (!reviewStates.includes(reviewState)) {\n    return asToolResult(`Unsupported review state: ${reviewState}.`, { allowedStates: reviewStates });\n  }\n\n  let target;\n  if (targetType === \"action\") {\n    target = getAction(targetId);\n    if (target) target.state = reviewState;\n  } else if (targetType === \"theme\") {\n    target = getTheme(targetId);\n    if (target) target.reviewState = reviewState;\n  } else if (targetType === \"claim\") {\n    target = state.brief.sections.find((section) => section.id === targetId);\n    if (target) target.reviewState = reviewState;\n  }\n\n  if (!target) {\n    return asToolResult(`${targetType} ${targetId} was not found.`, { updated: false });\n  }\n\n  addAudit(\"Agent\", `Marked ${targetType} ${labelFor(reviewState)}`, target.title || target.name || target.label);\n  saveState();\n  render();\n\n  return asToolResult(`Marked ${targetType} ${targetId} as ${labelFor(reviewState)}.`, {\n    updated: true,\n    targetType,\n    targetId,\n    reviewState,\n  });\n}\n\nfunction getAuditTrailTool({ limit = 8 } = {}) {\n  const safeLimit = Math.max(1, Math.min(Number(limit) || 8, 20));\n  return asToolResult(`Returning ${Math.min(safeLimit, state.auditTrail.length)} audit entries.`, {\n    auditTrail: state.auditTrail.slice(0, safeLimit),\n  });\n}\n\nasync function registerWebMcpTools() {\n  const modelContext = getModelContext();\n  window.SignalDeskWebMCP = {\n    available: Boolean(modelContext),\n    tools: webMcpToolNames,\n  };\n\n  if (!modelContext?.registerTool) {\n    updateToolStatus(\"unavailable\", \"WebMCP unavailable\");\n    return;\n  }\n\n  const controller = new AbortController();\n  window.addEventListener(\"pagehide\", () => controller.abort(), { once: true });\n\n  const tools = [\n    {\n      name: \"search_signals\",\n      description:\n        \"Search Signal Desk evidence by query, priority, and confidence. Returns signal summaries without changing app state.\",\n      inputSchema: {\n        type: \"object\",\n        properties: {\n          query: { type: \"string\", description: \"Keyword or phrase to search for.\" },\n          priority: { type: \"string\", enum: [\"all\", \"critical\", \"high\", \"medium\"] },\n          confidence: { type: \"string\", enum: [\"all\", \"high\", \"medium\"] },\n          limit: { type: \"integer\", minimum: 1, maximum: 20 },\n        },\n        additionalProperties: false,\n      },\n      execute: searchSignalsTool,\n    },\n    {\n      name: \"cluster_signals\",\n      description:\n        \"Refresh visible theme support from selected signals while preserving evidence links and adding an agent audit event.\",\n      inputSchema: {\n        type: \"object\",\n        properties: {\n          signalIds: { type: \"array\", items: { type: \"string\" } },\n          minConfidence: { type: \"string\", enum: [\"medium\", \"high\"] },\n        },\n        additionalProperties: false,\n      },\n      execute: clusterSignalsTool,\n    },\n    {\n      name: \"draft_brief\",\n      description:\n        \"Draft evidence-linked brief claims from selected themes and update the visible brief editor.\",\n      inputSchema: {\n        type: \"object\",\n        properties: {\n          themeIds: { type: \"array\", items: { type: \"string\" } },\n          title: { type: \"string\" },\n        },\n        additionalProperties: false,\n      },\n      execute: draftBriefTool,\n    },\n    {\n      name: \"explain_evidence\",\n      description:\n        \"Explain the evidence supporting a theme or brief claim. Returns the linked signals and does not change app state.\",\n      inputSchema: {\n        type: \"object\",\n        properties: {\n          targetType: { type: \"string\", enum: [\"theme\", \"claim\"] },\n          targetId: { type: \"string\" },\n        },\n        additionalProperties: false,\n      },\n      execute: explainEvidenceTool,\n    },\n    {\n      name: \"propose_actions\",\n      description:\n        \"Create approval-gated action proposals from selected themes and add them to the visible review queue.\",\n      inputSchema: {\n        type: \"object\",\n        properties: {\n          themeIds: { type: \"array\", items: { type: \"string\" } },\n          owner: { type: \"string\" },\n        },\n        additionalProperties: false,\n      },\n      execute: proposeActionsTool,\n    },\n    {\n      name: \"set_review_state\",\n      description:\n        \"Set review state for an action, theme, or brief claim. This records an agent audit event.\",\n      inputSchema: {\n        type: \"object\",\n        properties: {\n          targetType: { type: \"string\", enum: [\"action\", \"theme\", \"claim\"] },\n          targetId: { type: \"string\" },\n          reviewState: { type: \"string\", enum: reviewStates },\n        },\n        required: [\"targetType\", \"targetId\", \"reviewState\"],\n        additionalProperties: false,\n      },\n      execute: setReviewStateTool,\n    },\n    {\n      name: \"get_audit_trail\",\n      description:\n        \"Return recent human and agent changes from the Signal Desk audit trail without changing app state.\",\n      inputSchema: {\n        type: \"object\",\n        properties: {\n          limit: { type: \"integer\", minimum: 1, maximum: 20 },\n        },\n        additionalProperties: false,\n      },\n      execute: getAuditTrailTool,\n    },\n    {\n      name: \"reset_demo\",\n      description:\n        \"Reset Signal Desk to its seeded challenge demo scenario and record that the agent reset it.\",\n      inputSchema: {\n        type: \"object\",\n        properties: {},\n        additionalProperties: false,\n      },\n      execute: () => {\n        resetDemoWithAudit(\"Agent\");\n        return asToolResult(\"Reset the Signal Desk demo scenario.\", {\n          signals: state.signals.length,\n          themes: state.themes.length,\n          actions: state.actions.length,\n        });\n      },\n    },\n  ];\n\n  try {\n    for (const tool of tools) {\n      await modelContext.registerTool(tool, { signal: controller.signal });\n    }\n    window.SignalDeskWebMCP.available = true;\n    window.SignalDeskWebMCP.abort = () => controller.abort();\n    updateToolStatus(\"available\", `${tools.length} WebMCP tools`);\n  } catch (error) {\n    console.error(\"Signal Desk WebMCP registration failed\", error);\n    updateToolStatus(\"unavailable\", \"WebMCP registration failed\");\n  }\n}\n\nels.signalFilters.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\"[data-filter]\");\n  if (!button) return;\n  activeFilter = button.dataset.filter;\n  render();\n});\n\nels.signalList.addEventListener(\"click\", (event) => {\n  const card = event.target.closest(\"[data-signal-id]\");\n  if (!card) return;\n  selectSignal(card.dataset.signalId);\n});\n\nels.briefContent.addEventListener(\"click\", (event) => {\n  const stateButton = event.target.closest(\"[data-state]\");\n  const claimControls = event.target.closest(\"[data-claim-id]\");\n  if (stateButton && claimControls) {\n    setHumanReviewState(\"claim\", claimControls.dataset.claimId, stateButton.dataset.state);\n    return;\n  }\n\n  const button = event.target.closest(\"[data-signal-id]\");\n  if (!button) return;\n  selectSignal(button.dataset.signalId);\n});\n\nels.themeList.addEventListener(\"click\", (event) => {\n  const stateButton = event.target.closest(\"[data-state]\");\n  const reviewControls = event.target.closest(\"[data-review-theme-id]\");\n  if (stateButton && reviewControls) {\n    setHumanReviewState(\"theme\", reviewControls.dataset.reviewThemeId, stateButton.dataset.state);\n    return;\n  }\n\n  const card = event.target.closest(\"[data-theme-id]\");\n  if (!card) return;\n  state.activeThemeId = card.dataset.themeId;\n  saveState();\n  render();\n});\n\nels.actionList.addEventListener(\"click\", (event) => {\n  const evidenceButton = event.target.closest(\"[data-signal-id]\");\n  if (evidenceButton) {\n    selectSignal(evidenceButton.dataset.signalId);\n    return;\n  }\n\n  const button = event.target.closest(\"[data-state]\");\n  const controls = event.target.closest(\"[data-action-id]\");\n  if (!button || !controls) return;\n  setHumanReviewState(\"action\", controls.dataset.actionId, button.dataset.state);\n});\n\nels.signalSearch.addEventListener(\"input\", (event) => {\n  searchTerm = event.target.value.trim().toLowerCase();\n  render();\n});\n\nels.resetDemo.addEventListener(\"click\", resetDemo);\n\nels.selectCritical.addEventListener(\"click\", () => {\n  activeFilter = \"critical\";\n  searchTerm = \"\";\n  els.signalSearch.value = \"\";\n  const criticalSignal = state.signals.find((signal) => signal.priority === \"critical\");\n  if (criticalSignal) state.activeSignalId = criticalSignal.id;\n  render();\n});\n\nrender();\nregisterWebMcpTools();\n"},"/src/data.js":{"contentType":"text/javascript; charset=utf-8","body":"export const initialState = {\n  activeSignalId: \"sig-002\",\n  activeThemeId: \"theme-onboarding\",\n  lastUpdated: \"2026-08-26T14:55:00+05:30\",\n  signals: [\n    {\n      id: \"sig-001\",\n      source: \"Community Forum\",\n      sourceType: \"forum\",\n      author: \"Maya R.\",\n      channel: \"Launch Feedback\",\n      timestamp: \"2026-08-24T16:40:00+05:30\",\n      title: \"New users cannot find the migration checklist\",\n      excerpt:\n        \"The import worked, but I missed the setup checklist and only found it after searching docs for ten minutes.\",\n      url: \"https://example.com/community/migration-checklist\",\n      confidence: \"high\",\n      priority: \"high\",\n      themes: [\"theme-onboarding\", \"theme-docs\"],\n      evidenceTags: [\"docs\", \"activation\", \"migration\"],\n      status: \"unreviewed\",\n    },\n    {\n      id: \"sig-002\",\n      source: \"Support Inbox\",\n      sourceType: \"support\",\n      author: \"Support Triage\",\n      channel: \"Tier 1\",\n      timestamp: \"2026-08-25T09:25:00+05:30\",\n      title: \"Spike in workspace import tickets\",\n      excerpt:\n        \"Seven tickets in 24 hours mention import success followed by confusion about the next required admin step.\",\n      url: \"https://example.com/support/import-ticket-cluster\",\n      confidence: \"high\",\n      priority: \"critical\",\n      themes: [\"theme-onboarding\"],\n      evidenceTags: [\"tickets\", \"activation\", \"admin\"],\n      status: \"selected\",\n    },\n    {\n      id: \"sig-003\",\n      source: \"Public Changelog Comment\",\n      sourceType: \"web\",\n      author: \"Eli K.\",\n      channel: \"Release Notes\",\n      timestamp: \"2026-08-25T13:10:00+05:30\",\n      title: \"Release notes hide the admin follow-up\",\n      excerpt:\n        \"The release note explains import formats well, but the admin handoff is buried below the API examples.\",\n      url: \"https://example.com/changelog/import-release\",\n      confidence: \"medium\",\n      priority: \"medium\",\n      themes: [\"theme-docs\"],\n      evidenceTags: [\"release-notes\", \"admin\", \"docs\"],\n      status: \"unreviewed\",\n    },\n    {\n      id: \"sig-004\",\n      source: \"Customer Advisory Board\",\n      sourceType: \"meeting\",\n      author: \"CAB Notes\",\n      channel: \"August Review\",\n      timestamp: \"2026-08-23T18:05:00+05:30\",\n      title: \"Admins want a completion receipt\",\n      excerpt:\n        \"Two admins asked for a clear receipt that says what was imported, what failed, and what they should do next.\",\n      url: \"https://example.com/notes/admin-receipt\",\n      confidence: \"high\",\n      priority: \"high\",\n      themes: [\"theme-onboarding\", \"theme-trust\"],\n      evidenceTags: [\"admin\", \"receipt\", \"trust\"],\n      status: \"selected\",\n    },\n    {\n      id: \"sig-005\",\n      source: \"Competitor Watch\",\n      sourceType: \"market\",\n      author: \"Analyst Desk\",\n      channel: \"Ecosystem Scan\",\n      timestamp: \"2026-08-25T20:30:00+05:30\",\n      title: \"Competitor ships guided import receipt\",\n      excerpt:\n        \"A competitor now shows a guided post-import checklist with owners, dates, and one-click escalation.\",\n      url: \"https://example.com/market/guided-import-receipt\",\n      confidence: \"medium\",\n      priority: \"medium\",\n      themes: [\"theme-trust\"],\n      evidenceTags: [\"competitor\", \"checklist\", \"admin\"],\n      status: \"unreviewed\",\n    },\n    {\n      id: \"sig-006\",\n      source: \"Sales Call\",\n      sourceType: \"meeting\",\n      author: \"AE Summary\",\n      channel: \"Enterprise Pipeline\",\n      timestamp: \"2026-08-22T11:15:00+05:30\",\n      title: \"Buyer asks who owns post-import setup\",\n      excerpt:\n        \"The champion liked the importer, then asked whether IT, RevOps, or the vendor owns the final validation step.\",\n      url: \"https://example.com/sales/post-import-ownership\",\n      confidence: \"medium\",\n      priority: \"medium\",\n      themes: [\"theme-onboarding\", \"theme-trust\"],\n      evidenceTags: [\"sales\", \"ownership\", \"validation\"],\n      status: \"unreviewed\",\n    },\n  ],\n  themes: [\n    {\n      id: \"theme-onboarding\",\n      name: \"Post-import onboarding gap\",\n      summary:\n        \"Users complete the import but do not know the required next step, owner, or validation path.\",\n      signalIds: [\"sig-001\", \"sig-002\", \"sig-004\", \"sig-006\"],\n      confidence: \"high\",\n      reviewState: \"needs_edit\",\n    },\n    {\n      id: \"theme-docs\",\n      name: \"Docs and release notes bury next steps\",\n      summary:\n        \"The guidance exists, but it is split across docs and release notes instead of appearing in the workflow.\",\n      signalIds: [\"sig-001\", \"sig-003\"],\n      confidence: \"medium\",\n      reviewState: \"proposed\",\n    },\n    {\n      id: \"theme-trust\",\n      name: \"Admins need proof and ownership\",\n      summary:\n        \"Admins want a receipt that clarifies import outcomes, unresolved items, and accountable owners.\",\n      signalIds: [\"sig-004\", \"sig-005\", \"sig-006\"],\n      confidence: \"medium\",\n      reviewState: \"proposed\",\n    },\n  ],\n  brief: {\n    title: \"Launch Intelligence Brief: Import Activation\",\n    status: \"draft\",\n    updatedBy: \"Seed scenario\",\n    sections: [\n      {\n        id: \"claim-001\",\n        label: \"Primary risk\",\n        claim:\n          \"The import launch is creating an activation gap after technical success, especially for admin-owned workspaces.\",\n        evidenceSignalIds: [\"sig-002\", \"sig-004\", \"sig-006\"],\n        reviewState: \"needs_edit\",\n      },\n      {\n        id: \"claim-002\",\n        label: \"Evidence pattern\",\n        claim:\n          \"The strongest signals cluster around missing next-step ownership, not import failures.\",\n        evidenceSignalIds: [\"sig-001\", \"sig-002\", \"sig-004\"],\n        reviewState: \"proposed\",\n      },\n      {\n        id: \"claim-003\",\n        label: \"Opportunity\",\n        claim:\n          \"A post-import receipt with owners and validation steps would directly address support, customer, and market signals.\",\n        evidenceSignalIds: [\"sig-004\", \"sig-005\"],\n        reviewState: \"proposed\",\n      },\n    ],\n  },\n  actions: [\n    {\n      id: \"act-001\",\n      title: \"Add post-import receipt to the product flow\",\n      owner: \"Product\",\n      due: \"2026-08-30\",\n      rationale:\n        \"The receipt addresses the highest-confidence support and advisory board signals.\",\n      evidenceSignalIds: [\"sig-002\", \"sig-004\"],\n      state: \"proposed\",\n    },\n    {\n      id: \"act-002\",\n      title: \"Move migration checklist above API examples\",\n      owner: \"Docs\",\n      due: \"2026-08-28\",\n      rationale:\n        \"Docs feedback suggests next steps are present but not findable at the moment of need.\",\n      evidenceSignalIds: [\"sig-001\", \"sig-003\"],\n      state: \"needs_edit\",\n    },\n    {\n      id: \"act-003\",\n      title: \"Prepare admin handoff email template\",\n      owner: \"Lifecycle\",\n      due: \"2026-09-02\",\n      rationale:\n        \"Sales and CAB evidence both point to ownership confusion after import completion.\",\n      evidenceSignalIds: [\"sig-004\", \"sig-006\"],\n      state: \"approved\",\n    },\n  ],\n  auditTrail: [\n    {\n      id: \"audit-001\",\n      actor: \"Agent\",\n      action: \"Clustered 6 signals into 3 themes\",\n      timestamp: \"2026-08-26T14:49:00+05:30\",\n      detail: \"Grouped signals by activation, documentation, and trust patterns.\",\n    },\n    {\n      id: \"audit-002\",\n      actor: \"Agent\",\n      action: \"Drafted 3 brief claims with evidence\",\n      timestamp: \"2026-08-26T14:51:00+05:30\",\n      detail: \"Each claim includes at least two supporting signals.\",\n    },\n    {\n      id: \"audit-003\",\n      actor: \"Human\",\n      action: \"Approved lifecycle handoff action\",\n      timestamp: \"2026-08-26T14:54:00+05:30\",\n      detail: \"Kept product and docs actions in review.\",\n    },\n  ],\n};\n"}};

function withSecurityHeaders(response) {
  const headers = new Headers(response.headers);
  headers.set("x-content-type-options", "nosniff");
  headers.set("referrer-policy", "strict-origin-when-cross-origin");
  headers.set("permissions-policy", "camera=(), microphone=(), geolocation=()");
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const route = assets[url.pathname] ? url.pathname : "/";
    const asset = assets[route];

    return withSecurityHeaders(
      new Response(asset.body, {
        headers: {
          "content-type": asset.contentType,
          "cache-control": "no-store",
        },
      }),
    );
  },
};
